mapper.select:
SELECT * FROM LEAVE_REQUESTS


        AND status = #{status}



        AND EXTRACT(MONTH FROM COALESCE(effective_date, start_date)) = #{month}



        AND EXTRACT(YEAR FROM COALESCE(effective_date, start_date)) = #{year}


ORDER BY
CASE WHEN status = 'PENDING' THEN 1 ELSE 2 END,
created_at DESC
LIMIT #{size} OFFSET #{offset}
